head.script:
/**************************************************************************
 * Event : scwin.grdData1_ontoggleclick
 * 기 능 : 그리드 토글 버튼 클릭 이벤트(병합 다시 적용)
 **************************************************************************/
scwin.grdData1_ontoggleclick = function() {
	grdData1.mergeClear();
	scwin.gridMergeCol();
};

/***************************************************************************
 * 함수명 : scwin.gridMergeCol
 * 기능 : 그리드 컬럼 병합
 ***************************************************************************/
scwin.gridMergeCol = function() {
	grdData1.mergeClear();
	grdData1.mergeCol( 0 , true );
	grdData1.mergeCol( 1 , true );
	grdData1.mergeCol( 2 , true );
	grdData1.mergeCol( 3 , true );
	grdData1.mergeCol( 4 , true );
	grdData1.mergeCol( 5 , true );
	grdData1.mergeCol( 6 , true );
	grdData1.mergeCol( 7 , false );
	grdData1.mergeCol( 8 , false );
	grdData1.mergeCol( 9 , false );
	grdData1.mergeCol( 10 , false );
	grdData1.mergeByCol( );
};

scwin.checkVal = function() {
	return (document.getElementById('grdData1_cell_4_4') || document.getElementById('mf_grdData1_cell_4_4')).getAttribute('rowspan') == 2;
};
